const SUPABASE_URL = 'https://cvgrlrolpxysctayljwy.supabase.co';
const BUCKET = 'honda';

const modifications = {};
let index = 1;

for (const item of items) {
  let key =
    item.json.Key ||
    item.json.key ||
    item.json.path ||
    item.json.fullPath ||
    item.json.full_path;

  if (!key) continue;

  // Nếu Supabase trả về "honda/videos/scene-1.mp4"
  // thì bỏ phần "honda/" để tránh bị lặp bucket
  if (key.startsWith(`${BUCKET}/`)) {
    key = key.replace(`${BUCKET}/`, '');
  }

  const publicUrl = `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${key}`;

  modifications[`Video-${index}.source`] = publicUrl;
  index++;
}

return [
  {
    json: {
      modifications
    }
  }
];

